#!/usr/bin/env bash
# Chapitre « Les espaces collaboratifs » (partie Membres et collaboration) + sommaire.
# Prérequis : apply-formats-autorises.sh.
# Usage (racine du repo) : bash apply-docs-espaces-collaboratifs.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/membres/espaces-collaboratifs.mdx" 2>/dev/null | grep -qF "title: \"Les espaces collaboratifs\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "uploadTypeError" "packages/backend/src/modules/storage/router.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-formats-autorises.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/index.mdx")
CREATED=("apps/web/content/docs/dev/membres/espaces-collaboratifs.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "title: \"Les espaces collaboratifs\"" "apps/web/content/docs/dev/membres/espaces-collaboratifs.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/membres"
base64 -d > "apps/web/content/docs/dev/membres/espaces-collaboratifs.mdx" <<'B64'
